#include <iostream>
#include <print>

struct Rect {
    double width = 0;
    double height = 0;

    double area() const {
        return width * height;
    }

    double perimeter() const {
        return 2 * (width + height);
    }

    bool is_square() const {
        return width == height;
    }
};

int main() {
    Rect r;
    while (std::cin >> r.width >> r.height) {
        std::println("площадь {:.2f}, периметр {:.2f}, квадрат: {}", r.area(), r.perimeter(),
                     r.is_square() ? "да" : "нет");
    }
    return 0;
}

